import { carriedAnswer, gateStep, planTurn, studioAgentTools, TURN_REFUSALS, turnHoldMicroUsd } from '@/lib/studio-agent-rules';
import { is, done } from '@/tests/check';
const encoder=new TextEncoder();
const hold=turnHoldMicroUsd()!;
for(const value of [null,NaN,Infinity,-Infinity,-1,1.5,Number.MAX_SAFE_INTEGER+1]) is(`unknown budget ${String(value)} refuses`,planTurn(1,value).ok,false);
for(const value of [NaN,Infinity,-1,0,0.5,2001,Number.MAX_SAFE_INTEGER]) is(`invalid ask bound ${String(value)} refuses`,planTurn(value,hold).ok,false);
for(const char of ['a','é','中','😀']) for(const size of [1,4095,4096,4097]) {
  const text=char.repeat(size),value=carriedAnswer(text);
  is(`UTF8 ${encoder.encode(char).length} byte char x${size} output bounded`,encoder.encode(value.text).length<=4096,true);
  is(`UTF8 ${encoder.encode(char).length} byte char x${size} preserved when fits`,value.cut,encoder.encode(text).length>4096);
}
for(const name of ['__proto__','constructor','toString','confirm_proposal','send_email','unknown']){
  is(`unlisted ${name} not offered`,studioAgentTools(()=>true,[{name,annotations:{readOnlyHint:true}}]),[]);
  is(`unlisted ${name} cannot pass even forged offered list`,gateStep(name,[name],0).ok,false);
}
is('deny permissions retains only team-member store context',studioAgentTools(()=>false),['get_store']);
is('read hint must be exactly boolean true',studioAgentTools(()=>true,[{name:'get_numbers',annotations:{readOnlyHint:1 as never}}]),[]);
is('propose hint must be exactly boolean false',studioAgentTools(()=>true,[{name:'propose_product_description',annotations:{readOnlyHint:0 as never}}]),[]);
is('one less than hold refused',planTurn(1,hold-1).ok,false);
is('exact hold admitted',planTurn(2000,hold).ok,true);
const ask='中'.repeat(1000),bytes=encoder.encode(ask).length;
is('1000-character UTF8 message is refused by actual byte boundary',planTurn(bytes,hold).ok,false);
console.log('LOW_REPRO',JSON.stringify({characters:[...ask].length,bytes,message:TURN_REFUSALS.too_long}));
is('LOW: refusal advice describes the actual UTF8/byte constraint',/bytes|UTF-8/.test(TURN_REFUSALS.too_long),true);
done();

